const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300;

const item = $input.first();
const root = item.json || {};
const headers = (root.headers && typeof root.headers === 'object') ? root.headers : {};
const availableHeaderKeys = Object.keys(headers);

function readHeader(name) {
  const variants = [name, name.toLowerCase(), name.toUpperCase()];
  for (const key of variants) {
    const value = headers[key] ?? root[key];
    if (Array.isArray(value) && value.length > 0) return String(value[0]);
    if (typeof value === 'string' || typeof value === 'number') return String(value);
  }
  return '';
}

const sigHeader = readHeader('X-EduAI-Signature-256');
const tsHeader  = readHeader('X-EduAI-Timestamp');
const idempKey  = readHeader('X-EduAI-Idempotency-Key');

if (!sigHeader) {
  throw new Error(`Missing X-EduAI-Signature-256; available header keys: ${availableHeaderKeys.join(', ') || '(none)'}`);
}
if (!tsHeader) {
  throw new Error(`Missing X-EduAI-Timestamp; available header keys: ${availableHeaderKeys.join(', ') || '(none)'}`);
}

const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s`);
}

const rawBody  = typeof root.rawBody === 'string' ? root.rawBody : JSON.stringify(root.body || root.payload || root);
const expected = 'sha256=' + crypto.createHmac('sha256', HMAC_SECRET).update(rawBody, 'utf8').digest('hex');
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

const ALLOWED_ROLES = ['professor'];
const item = $input.first();
const role = (item.json.payload || {}).role || '';
if (!ALLOWED_ROLES.includes(role)) {
  throw new Error(`Role '${role}' rejected in professor assessment workflow.`);
}
return [{ json: { ...item.json, _role_validated: true } }];

const openaiRaw = $node['Call OpenAI (Primary)'].json;
const claudeRaw = $node['Call Claude (Reviewer)'].json;

let openaiResult;
try {
  const content = openaiRaw.choices[0].message.content;
  openaiResult = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Failed to parse OpenAI response: ' + e.message);
}

let claudeResult;
try {
  const content = claudeRaw.content[0].text;
  claudeResult = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Failed to parse Claude response: ' + e.message);
}

const openaiConfidence = openaiResult.confidence || 0;
const claudeVerdict = claudeResult.overall_verdict || 'approved';
const escalationReasons = [];
if (openaiConfidence < 0.40) escalationReasons.push('openai_confidence_low: ' + openaiConfidence);
if (claudeVerdict === 'escalate') escalationReasons.push('claude_verdict_escalate');
if (openaiResult.needs_human_review) escalationReasons.push('openai_needs_human_review');

const shouldEscalate = escalationReasons.length > 0;

const openaiUsage = openaiRaw.usage || {};
openaiResult.usage = { model: 'gpt-4o', prompt_tokens: openaiUsage.prompt_tokens || 0, completion_tokens: openaiUsage.completion_tokens || 0, total_tokens: openaiUsage.total_tokens || 0, latency_ms: 0, cost_usd: ((openaiUsage.prompt_tokens || 0) * 0.000005 + (openaiUsage.completion_tokens || 0) * 0.000015) };

const claudeUsage = claudeRaw.usage || {};
claudeResult.usage = { model: 'claude-sonnet-4-6', prompt_tokens: claudeUsage.input_tokens || 0, completion_tokens: claudeUsage.output_tokens || 0, total_tokens: (claudeUsage.input_tokens || 0) + (claudeUsage.output_tokens || 0), latency_ms: 0, cost_usd: ((claudeUsage.input_tokens || 0) * 0.000003 + (claudeUsage.output_tokens || 0) * 0.000015) };

const gateDecision = { pass_gate: !shouldEscalate, escalate: shouldEscalate, hitl_required: shouldEscalate, escalation_reasons: escalationReasons, final_confidence: (openaiConfidence + (claudeResult.reviewer_confidence || 0)) / 2, confidence_sources: { openai: openaiConfidence, claude: claudeResult.reviewer_confidence || 0 }, decided_at: new Date().toISOString() };

const eventPayload = $node['Verify HMAC'].json.payload || {};
const idempKey = $node['Verify HMAC'].json._idempotency_key || $node['Verify HMAC'].json.event_id;

return [{ json: { event_id: idempKey, file_id: eventPayload.file_id, submission_id: eventPayload.submission_id || '', user_id: eventPayload.user_id, openai_result: openaiResult, claude_review: claudeResult, gate_decision: gateDecision, _should_escalate: shouldEscalate, _escalation_reasons: escalationReasons, _openai_confidence: openaiConfidence } }];
